#![allow(clippy::approx_constant)]
//! (A baked coordinate that lands near 2/pi or log10(e) is a coordinate,
//! not a constant anyone meant to write.)
//! DejaVu Sans glyph outlines, baked.
//!
//! Blender's Text object is a **font curve**: the glyph's outline is the
//! curve and `Curve.ext1` (Geometry ▸ Extrude) gives it depth. Reading a
//! TTF at run time would mean a font parser in the crate; baking one
//! font's outlines is the same geometry with none of that, and the
//! geometry is what the mesh wants. Generated by `tooling/bake_font.py`
//! from DejaVuSans.ttf (Bitstream Vera / DejaVu licence) at a flattening
//! tolerance of 0.012 em, in em units with the baseline at y = 0.

/// One glyph: its advance width in em, and its contours.
pub struct Glyph {
    pub advance: f32,
    pub contour: &'static [&'static [(f32, f32)]],
}

